from typing import Optional, TypeVar

T = TypeVar('T')

def find(lst: list[T], pred) -> Optional[T]:
    for x in lst:
        if pred(x):
            return x
    return None

scores: dict[str, int] = {'Alice': 92}
first = find([1, 3, 5], lambda x: x > 2)
print(scores['Alice'], first)
print(find([1, 2], lambda x: x > 9))

def average(nums: list[float]) -> float:
    return sum(nums) / len(nums)

print(average([1.5, 2.5]))

from typing import TypeVar, Generic

T = TypeVar('T')

class Stack(Generic[T]):
    def __init__(self) -> None:
        self._items: list[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        return self._items.pop()

s = Stack[int]()
s.push(1)
s.push(2)
print(s.pop(), s.pop())
